// Verify Stripe signature — fail-closed if signature doesn't match.
// This guards against forged webhook calls.
const crypto = require('crypto');
const sig = $input.first().headers['stripe-signature'];
const secret = $node['SET_DEFAULTS'].json['stripe_webhook_secret'];
const rawBody = $input.first().body;

if (!sig || !secret || secret.startsWith('<')) {
  return [{ json: { ok: false, error: 'missing_signature_or_secret' } }];
}

const parts = sig.split(',').reduce((acc, p) => {
  const [k, v] = p.split('='); acc[k] = v; return acc;
}, {});

const expected = crypto.createHmac('sha256', secret)
  .update(parts.t + '.' + JSON.stringify(rawBody))
  .digest('hex');

if (expected !== parts.v1) {
  return [{ json: { ok: false, error: 'signature_mismatch' } }];
}

return [{ json: { ok: true, event: rawBody } }];
